using System.Collections.Generic;
using System.Linq;
using Rapadura.Core.Localization;

namespace Rapadura.Gameplay.Dialogue
{
    /// <summary>
    /// Localization entries for the quest-giver dialogues (new <c>dialogue.*</c> keys). Same pattern as
    /// <c>QuestLogTexts</c>: kept out of <c>LocalizationManager.DefaultEntries</c> so that shared file
    /// isn't edited, merged at runtime by <see cref="EnsureLoaded"/> (only keys not yet registered).
    /// </summary>
    public static class QuestGiverTexts
    {
        public static readonly List<LocalizationEntry> All = new List<LocalizationEntry>
        {
            // -- dialogue_village_survivor — gives quest_joaquim_echoes_of_home --
            new LocalizationEntry("dialogue.village_survivor.recognize_cousin", "Wait... those eyes. You're one of Joaquim's cousins, aren't you? He used to talk about you all the time — how his family would come for him one day.", "Espera... esses olhos. Você é um dos primos do Joaquim, não é? Ele vivia falando de vocês — que a família dele viria buscá-lo um dia."),
            new LocalizationEntry("dialogue.village_survivor.recognize_joaquim", "Joaquim? Little Joaquim, the boy who dragged that giant shield everywhere? Roots be thanked, you're alive! Twelve years old and still standing in front of everyone, I bet.", "Joaquim? O pequeno Joaquim, o menino que arrastava aquele escudo gigante pra todo lado? Graças às raízes, você está vivo! Doze anos e ainda se colocando na frente de todo mundo, aposto."),
            new LocalizationEntry("dialogue.village_survivor.recognize_maria", "You have your brother's stubborn chin. You're Maria, the temple girl! Joaquim always said his big sister glowed when she was angry. Is he... is he with you?", "Você tem o queixo teimoso do seu irmão. Você é a Maria, a menina do templo! O Joaquim sempre dizia que a irmã mais velha brilhava quando ficava brava. Ele... ele está com você?"),
            new LocalizationEntry("dialogue.village_survivor.accept_joaquim", "Follow the old well path past the fallen gate. The guardian's blade is yours by right, boy — your grandfather would want it in your hands, not buried in the dirt. Just... don't fight them all alone this time.", "Siga a trilha do velho poço além do portão caído. A lâmina do guardião é sua por direito, menino — seu avô ia querer ela nas suas mãos, não enterrada na terra. Só... não enfrente todos sozinho dessa vez."),
            new LocalizationEntry("dialogue.village_survivor.active", "The creatures still crawl in the ruins — I hear them at night. The blade should be past the fallen gate, down the old well path. Come back and tell me when it's quiet again.", "As criaturas ainda rastejam nas ruínas — eu ouço elas à noite. A lâmina deve estar além do portão caído, descendo a trilha do velho poço. Volte e me conte quando estiver tudo quieto de novo."),
            new LocalizationEntry("dialogue.village_survivor.completed_cousin", "The ruins are quiet. For the first time since that night I slept until sunrise. Tell Joaquim the village remembers him — and that his family made it safe again.", "As ruínas estão em silêncio. Pela primeira vez desde aquela noite eu dormi até o sol nascer. Diga ao Joaquim que a vila se lembra dele — e que a família dele a deixou segura de novo."),
            new LocalizationEntry("dialogue.village_survivor.completed_joaquim", "You did it, Joaquim. The ruins are quiet and the blade is back where it belongs. You kept your promise — now go keep the next one, and let your cousins stand beside you for a change.", "Você conseguiu, Joaquim. As ruínas estão em silêncio e a lâmina voltou pra quem é de direito. Você cumpriu sua promessa — agora vá cumprir a próxima, e deixe seus primos ficarem do seu lado pra variar."),

            // -- dialogue_windtrail_scholar — gives / hands in quest_maithe_windtrail --
            new LocalizationEntry("dialogue.windtrail_scholar.offer_cousin", "You're family of that huntress, aren't you? Same way of watching the ridgeline. Bring me proof: fell four of the marked golems and carry back three ore samples with the mark on them. Then we'll see what Maithe's eye makes of it.", "Você é da família daquela caçadora, não é? Mesmo jeito de vigiar a crista da montanha. Me traga provas: derrube quatro dos golens marcados e traga três amostras de minério com a marca. Aí veremos o que o olho da Maithe acha disso."),
            new LocalizationEntry("dialogue.windtrail_scholar.choice_accept", "I'll bring you proof.", "Eu vou trazer as provas."),
            new LocalizationEntry("dialogue.windtrail_scholar.choice_decline", "Not yet. I need to prepare.", "Ainda não. Preciso me preparar."),
            new LocalizationEntry("dialogue.windtrail_scholar.offer_maithe", "So you're Maithe. Fourteen, and the hunters already say you outshoot them. That eye of yours sees what I can't — fell four marked golems, bring three marked ore samples, and we'll read these glyphs together.", "Então você é a Maithe. Catorze anos, e os caçadores já dizem que você atira melhor que eles. Esse seu olho vê o que eu não vejo — derrube quatro golens marcados, traga três amostras de minério com a marca, e vamos ler esses símbolos juntos."),
            new LocalizationEntry("dialogue.windtrail_scholar.choice_accept_maithe", "Four golems, three samples. Easy.", "Quatro golens, três amostras. Fácil."),
            new LocalizationEntry("dialogue.windtrail_scholar.offer_icaro", "You must be the little brother — the one with the gadgets. Your sister's been chasing this mark for years. Fell four of the marked golems and bring three marked ore samples; if anyone can build something from it, it's you two.", "Você deve ser o irmão mais novo — o dos inventos. Sua irmã persegue essa marca há anos. Derrube quatro golens marcados e traga três amostras de minério com a marca; se alguém pode fazer algo com isso, são vocês dois."),
            new LocalizationEntry("dialogue.windtrail_scholar.choice_accept_icaro", "Maithe's going to be so jealous I got here first.", "A Maithe vai morrer de inveja que eu cheguei primeiro."),
            new LocalizationEntry("dialogue.windtrail_scholar.accepted", "The golems patrol the high trail. Mind the wind up there — it hides their footsteps.", "Os golens patrulham a trilha alta. Cuidado com o vento lá em cima — ele esconde os passos deles."),
            new LocalizationEntry("dialogue.windtrail_scholar.declined", "Wise. The mountain doesn't forgive the careless.", "Sábio. A montanha não perdoa os descuidados."),
            new LocalizationEntry("dialogue.windtrail_scholar.active", "Four marked golems, three marked ore samples. The mark looks like an eye inside a spiral — you can't miss it once you know it.", "Quatro golens marcados, três amostras de minério marcadas. A marca parece um olho dentro de uma espiral — depois que você conhece, não tem como errar."),
            new LocalizationEntry("dialogue.windtrail_scholar.ready", "You brought them! Same spiral on every sample. Hold them up to the light — let's see what they really say.", "Você trouxe! A mesma espiral em todas as amostras. Segure contra a luz — vamos ver o que elas realmente dizem."),
            new LocalizationEntry("dialogue.windtrail_scholar.choice_decode", "Read the glyphs.", "Ler os símbolos."),
            new LocalizationEntry("dialogue.windtrail_scholar.decoded_cousin", "There — a name, half-erased, and a direction: deeper, past the mountains. Someone really did build these things. Take this to Maithe; it's her mystery, but it's your family's fight now.", "Ali — um nome, meio apagado, e uma direção: mais fundo, além das montanhas. Alguém realmente construiu essas coisas. Leve isso pra Maithe; o mistério é dela, mas a luta agora é da sua família."),
            new LocalizationEntry("dialogue.windtrail_scholar.decoded_maithe", "Your eye's glowing... the glyphs are rearranging! A name, half-erased, and a direction: deeper, past the mountains. You were right all along, Maithe. Someone built the monsters.", "Seu olho está brilhando... os símbolos estão se reorganizando! Um nome, meio apagado, e uma direção: mais fundo, além das montanhas. Você estava certa o tempo todo, Maithe. Alguém construiu os monstros."),
            new LocalizationEntry("dialogue.windtrail_scholar.completed", "I've copied every glyph into my notes. Whoever made those golems, they know about your family now — so stay together.", "Copiei cada símbolo nas minhas anotações. Quem quer que tenha feito aqueles golens, agora sabe da sua família — então fiquem juntos."),

            // -- dialogue_hermit_mystic — gives / hands in quest_lavine_redtide --
            new LocalizationEntry("dialogue.hermit_mystic.offer_cousin", "Something born of the Noite Rubra is calling a corrupted swarm to these caves — and it smells like your little cousin's power. Cull eight of them before they find her, and come back. Then I'll teach you what to say when the whispers come.", "Algo nascido da Noite Rubra está chamando um enxame corrompido pra estas cavernas — e tem o cheiro do poder da sua priminha. Extermine oito deles antes que a encontrem, e volte. Aí eu te ensino o que dizer quando os sussurros vierem."),
            new LocalizationEntry("dialogue.hermit_mystic.choice_accept", "I'll protect her.", "Eu vou protegê-la."),
            new LocalizationEntry("dialogue.hermit_mystic.choice_decline", "Not now.", "Agora não."),
            new LocalizationEntry("dialogue.hermit_mystic.offer_lavine", "So the child of the Noite Rubra comes herself. Only nine, and already carrying so much. The swarm follows your power, little one. Cull eight of them, then sit with me — and we'll teach those whispers who's in charge.", "Então a filha da Noite Rubra veio ela mesma. Só nove anos, e já carregando tanto. O enxame segue o seu poder, pequena. Extermine oito deles, depois sente comigo — e vamos ensinar a esses sussurros quem manda."),
            new LocalizationEntry("dialogue.hermit_mystic.choice_accept_lavine", "I'm not little. But... okay.", "Eu não sou pequena. Mas... tá bom."),
            new LocalizationEntry("dialogue.hermit_mystic.accepted", "Go before the swarm grows. And whatever you hear in the dark — it's not your voice.", "Vá antes que o enxame cresça. E o que quer que você ouça no escuro — não é a sua voz."),
            new LocalizationEntry("dialogue.hermit_mystic.declined", "The swarm will wait. The whispers, less so.", "O enxame vai esperar. Os sussurros, nem tanto."),
            new LocalizationEntry("dialogue.hermit_mystic.active", "Eight of the corrupted swarm. You'll feel them before you see them — a cold spot behind the ears.", "Oito do enxame corrompido. Você vai senti-los antes de vê-los — um ponto frio atrás das orelhas."),
            new LocalizationEntry("dialogue.hermit_mystic.ready_cousin", "The swarm is gone, but I can still hear it whispering — reaching for anyone of Lavine's blood. Sit. Breathe. Answer it.", "O enxame se foi, mas ainda ouço ele sussurrando — procurando qualquer um do sangue da Lavine. Sente. Respire. Responda."),
            new LocalizationEntry("dialogue.hermit_mystic.choice_resist", "\"You don't get her. She's got us.\"", "\"Você não fica com ela. Ela tem a gente.\""),
            new LocalizationEntry("dialogue.hermit_mystic.ready_lavine", "The swarm is gone, but the whispers aren't, are they? Sit, child. Breathe. Tell them who you are.", "O enxame se foi, mas os sussurros não, não é? Sente, criança. Respire. Diga a eles quem você é."),
            new LocalizationEntry("dialogue.hermit_mystic.choice_resist_lavine", "\"I'm Lavine. My power protects. And I'm not alone.\"", "\"Eu sou a Lavine. Meu poder protege. E eu não estou sozinha.\""),
            new LocalizationEntry("dialogue.hermit_mystic.resisted", "...Silence. Do you hear that? The eclipse in your family's blood just lost an argument. That's rarer than any spell.", "...Silêncio. Está ouvindo? O eclipse no sangue da sua família acabou de perder uma discussão. Isso é mais raro que qualquer feitiço."),
            new LocalizationEntry("dialogue.hermit_mystic.completed", "The caves are calm. Tell Lavine that being the youngest never made her the weakest — the whispers learned that the hard way.", "As cavernas estão calmas. Diga à Lavine que ser a mais nova nunca a fez a mais fraca — os sussurros aprenderam isso do jeito difícil."),

            // -- dialogue_temple_acolyte — gives quest_maria_fading_light --
            new LocalizationEntry("dialogue.temple_acolyte.intro_maria", "Maria! Thank the sun you're here. A shard in the mountain caves went dark last night — the same one from your vision, isn't it?", "Maria! Graças ao sol você está aqui. Um fragmento nas cavernas da montanha se apagou ontem à noite — o mesmo da sua visão, não é?"),
            new LocalizationEntry("dialogue.temple_acolyte.intro_joaquim", "You're Maria's little brother — the one she prays for every time you run off to fight something. A shard in the mountain caves went dark. She'd want you there with her.", "Você é o irmão mais novo da Maria — aquele por quem ela reza toda vez que sai correndo pra enfrentar alguma coisa. Um fragmento nas cavernas da montanha se apagou. Ela ia querer você lá com ela."),
            new LocalizationEntry("dialogue.temple_acolyte.intro_cousin", "You're one of Maria's cousins — she speaks of all of you in her prayers. A shard of our crystal network in the mountain caves has gone dark.", "Você é um dos primos da Maria — ela fala de todos vocês nas orações. Um fragmento da nossa rede de cristais nas cavernas da montanha se apagou."),
            new LocalizationEntry("dialogue.temple_acolyte.offer", "Cleanse five of the corrupted creatures around the shard and bring back two fragments that still glow. Then come tell me — the temple needs to know if the light can be saved.", "Purifique cinco das criaturas corrompidas em volta do fragmento e traga dois pedaços que ainda brilhem. Depois venha me contar — o templo precisa saber se a luz pode ser salva."),
            new LocalizationEntry("dialogue.temple_acolyte.choice_accept", "I'll go to the caves.", "Eu vou até as cavernas."),
            new LocalizationEntry("dialogue.temple_acolyte.choice_decline", "Not yet.", "Ainda não."),
            new LocalizationEntry("dialogue.temple_acolyte.accepted_cousin", "Go with the Templo Solar's blessing. And keep each other close — the light shines brighter when it's shared.", "Vá com a bênção do Templo Solar. E fiquem perto uns dos outros — a luz brilha mais quando é dividida."),
            new LocalizationEntry("dialogue.temple_acolyte.accepted_maria", "Go, Maria. You're only thirteen, but the crystals answer you like they answered the eldest priestesses. Bring the light back.", "Vá, Maria. Você só tem treze anos, mas os cristais te respondem como respondiam às sacerdotisas mais velhas. Traga a luz de volta."),
            new LocalizationEntry("dialogue.temple_acolyte.declined", "The light will hold a little longer. I'll keep watch.", "A luz vai aguentar mais um pouco. Eu fico de vigia."),
            new LocalizationEntry("dialogue.temple_acolyte.active", "Five corrupted creatures, two glowing fragments. The caves are cold, but the shard's light will guide you to it.", "Cinco criaturas corrompidas, dois fragmentos brilhantes. As cavernas são frias, mas a luz do fragmento vai te guiar até ele."),
            new LocalizationEntry("dialogue.temple_acolyte.completed_cousin", "The fragments you brought are glowing steadier every hour. Maria's family has given the temple hope again.", "Os fragmentos que você trouxe brilham mais firmes a cada hora. A família da Maria devolveu a esperança ao templo."),

            // -- dialogue_ruins_archivist — gives / hands in quest_icaro_ancient_gears --
            new LocalizationEntry("dialogue.ruins_archivist.intro_icaro", "Another tinkerer? Wait — you're the boy who built a drone out of a kettle! Eleven years old... The old guardian construct still stands watch over these ruins. Nobody's ever gotten past it.", "Outro inventor? Espera — você é o menino que fez um drone de uma chaleira! Onze anos... O antigo autômato guardião ainda vigia estas ruínas. Ninguém nunca passou por ele."),
            new LocalizationEntry("dialogue.ruins_archivist.intro_maithe", "You have the same stubborn look as that inventor boy, Ícaro. His big sister, I'd guess? He's been asking about these ruins for weeks. The guardian construct still stands watch.", "Você tem o mesmo olhar teimoso daquele menino inventor, o Ícaro. A irmã mais velha, imagino? Ele está perguntando dessas ruínas há semanas. O autômato guardião ainda vigia o lugar."),
            new LocalizationEntry("dialogue.ruins_archivist.intro_cousin", "Family of young Ícaro, the inventor? He's been asking about these ruins for weeks. The guardian construct still stands watch over them.", "Da família do jovem Ícaro, o inventor? Ele está perguntando dessas ruínas há semanas. O autômato guardião ainda vigia o lugar."),
            new LocalizationEntry("dialogue.ruins_archivist.offer", "Put the guardian down and bring me an intact tech fragment from its wreckage. Then we'll decode its inscriptions together — whatever they say.", "Derrote o guardião e me traga um fragmento tecnológico intacto dos destroços. Aí decifraremos as inscrições juntos — seja lá o que disserem."),
            new LocalizationEntry("dialogue.ruins_archivist.choice_accept", "Deal. I'll bring you the fragment.", "Combinado. Eu trago o fragmento."),
            new LocalizationEntry("dialogue.ruins_archivist.choice_decline", "Maybe later.", "Talvez depois."),
            new LocalizationEntry("dialogue.ruins_archivist.accepted", "The guardian wakes when you step on the old tiles. Watch its core — it glows right before it strikes.", "O guardião acorda quando você pisa nos ladrilhos antigos. Observe o núcleo dele — ele brilha logo antes de atacar."),
            new LocalizationEntry("dialogue.ruins_archivist.declined", "It's waited centuries. It can wait a little longer.", "Ele esperou séculos. Pode esperar mais um pouco."),
            new LocalizationEntry("dialogue.ruins_archivist.active", "The guardian, then an intact fragment from its wreckage. Don't let it near water — the old circuits hate it.", "O guardião, depois um fragmento intacto dos destroços. Não deixe ele perto de água — os circuitos antigos odeiam isso."),
            new LocalizationEntry("dialogue.ruins_archivist.ready_cousin", "You brought it back for Ícaro? Then let's see what the old world wrote on it.", "Você trouxe isso pro Ícaro? Então vamos ver o que o mundo antigo escreveu aí."),
            new LocalizationEntry("dialogue.ruins_archivist.completed", "I'm still copying the schematic. Tell Ícaro his sister was right to worry — and right to be proud of him.", "Ainda estou copiando o esquema. Diga ao Ícaro que a irmã dele estava certa em se preocupar — e certa em ter orgulho dele."),

            // -- dialogue_maria_gathering_point — gives quest_convergence_the_gathering --
            new LocalizationEntry("dialogue.maria_gathering_point.waiting", "Not everyone is ready yet. Each of us has something to finish first — go help where your heart pulls you. I'll be right here when the family's whole.", "Nem todo mundo está pronto ainda. Cada um de nós tem algo pra terminar antes — vá ajudar onde seu coração te puxar. Eu vou estar bem aqui quando a família estiver completa."),
            new LocalizationEntry("dialogue.maria_gathering_point.waiting_maria", "Maninha, you picked a great spot... but nobody's coming until everyone's done their part. The village, the mountain, the temple, the ruins, the caves — then we meet.", "Maninha, você escolheu um ótimo lugar... mas ninguém vem até todo mundo fazer a sua parte. A vila, a montanha, o templo, as ruínas, as cavernas — aí a gente se encontra."),
            new LocalizationEntry("dialogue.maria_gathering_point.offer_maria", "Maria! I got here first, for once. Everyone finished their part — the village, the mountain, the ruins, the caves, your temple. Your vision's waiting. Want me to call the others?", "Maria! Cheguei primeiro, pra variar. Todo mundo terminou sua parte — a vila, a montanha, as ruínas, as cavernas, o seu templo. Sua visão está esperando. Quer que eu chame os outros?"),
            new LocalizationEntry("dialogue.maria_gathering_point.choice_accept", "Call everyone. It's time.", "Chame todo mundo. Chegou a hora."),
            new LocalizationEntry("dialogue.maria_gathering_point.choice_decline", "Not yet — give me a moment.", "Ainda não — me dá um minuto."),
            new LocalizationEntry("dialogue.maria_gathering_point.offer_joaquim", "There you are, maninho. You held the line for everyone — now let me hold it with you. Everyone's done their part. Shall we call the family?", "Aí está você, maninho. Você segurou a linha por todo mundo — agora deixa eu segurar com você. Todo mundo fez a sua parte. Vamos chamar a família?"),
            new LocalizationEntry("dialogue.maria_gathering_point.offer_maithe", "Maithe. You're three months older and you never let me forget it — but I need my big cousin now. You found the proof you were looking for. Will you stand with us?", "Maithe. Você é três meses mais velha e nunca me deixa esquecer — mas agora eu preciso da minha prima mais velha. Você achou a prova que procurava. Vai ficar com a gente?"),
            new LocalizationEntry("dialogue.maria_gathering_point.offer_icaro", "Ícaro! Your fragment, Maithe's glyphs — they point to the same place. Bring your drone. Shall we call everyone?", "Ícaro! O seu fragmento, os símbolos da Maithe — eles apontam pro mesmo lugar. Traz o seu drone. Vamos chamar todo mundo?"),
            new LocalizationEntry("dialogue.maria_gathering_point.offer_lavine", "Lavine. In my vision there were five of us — and you were standing in the middle. Not behind. The middle. Ready to call the others?", "Lavine. Na minha visão éramos cinco — e você estava no meio. Não atrás. No meio. Pronta pra chamar os outros?"),
            new LocalizationEntry("dialogue.maria_gathering_point.offer_any", "Everyone has finished their part. It's time for the whole family to stand together. Shall I call them?", "Todo mundo terminou a sua parte. Chegou a hora da família inteira ficar junta. Posso chamá-los?"),
            new LocalizationEntry("dialogue.maria_gathering_point.started", "Then it begins. I'll send word — Maithe, Joaquim, Ícaro, Lavine. By the time the sun sets, the five of us will be here.", "Então começou. Vou mandar recado — Maithe, Joaquim, Ícaro, Lavine. Quando o sol se pôr, nós cinco vamos estar aqui."),
            new LocalizationEntry("dialogue.maria_gathering_point.later", "Take your time. Family waits for family.", "Sem pressa. Família espera família."),
            new LocalizationEntry("dialogue.maria_gathering_point.warlord", "The mountain warlord is the one behind the marked golems and the dark crystals. Up the high trail. Together this time — nobody goes ahead alone. Yes, Joaquim, that means you.", "O senhor da guerra da montanha é quem está por trás dos golens marcados e dos cristais apagados. Subindo a trilha alta. Juntos dessa vez — ninguém vai na frente sozinho. Sim, Joaquim, isso é com você."),
            new LocalizationEntry("dialogue.maria_gathering_point.completed", "We did it. Five cousins, one family. Whatever comes next for Rapadura — it finds all of us.", "Nós conseguimos. Cinco primos, uma família. O que vier agora pra Rapadura — vai encontrar todos nós."),
        };

        public static void EnsureLoaded(LocalizationManager localization)
        {
            if (localization == null)
            {
                return;
            }

            localization.LoadEntries(All.Where(entry => !localization.HasKey(entry.Key)).ToList());
        }
    }
}
